// HMAC-SHA256 Verification (ADR-005)
// Verifies webhook signature + timestamp freshness
// Safe crypto access: try global, fallback to require

var nodeCrypto;
try {
  if (typeof crypto !== 'undefined' && typeof crypto.createHmac === 'function') {
    nodeCrypto = crypto;
  } else {
    nodeCrypto = require('crypto');
  }
} catch (e) {
  nodeCrypto = require('crypto');
}

var item = $input.first();
var body = item.json.body || {};
var headers = item.json.headers || {};

// Read HMAC secret from environment
var secret = $env.WEBHOOK_HMAC_SECRET;
var tolerance = parseInt($env.WEBHOOK_TIMESTAMP_TOLERANCE || '300', 10);

if (!secret) {
  console.error('[HMAC] WEBHOOK_HMAC_SECRET not configured');
  return [{ json: { valid: false, error: 'HMAC secret not configured' } }];
}

// Extract signature and timestamp from headers
var signature = headers['x-signature'] || headers['X-Signature'] || '';
var timestamp = parseInt(headers['x-timestamp'] || headers['X-Timestamp'] || '0', 10);

if (!signature || !timestamp) {
  console.error('[HMAC] Missing signature or timestamp header');
  return [{ json: { valid: false, error: 'Missing signature or timestamp' } }];
}

// Replay protection: reject if timestamp is too old or too far in future
var now = Math.floor(Date.now() / 1000);
if (Math.abs(now - timestamp) > tolerance) {
  console.error('[HMAC] Timestamp expired: diff=' + Math.abs(now - timestamp) + 's tolerance=' + tolerance + 's');
  return [{ json: { valid: false, error: 'Timestamp expired or too far in future' } }];
}

// Compute expected signature (sorted keys to match Python json.dumps(sort_keys=True))
var payloadStr = JSON.stringify(body, Object.keys(body).sort());
var message = payloadStr + '.' + timestamp;
var expectedSig = 'sha256=' + nodeCrypto.createHmac('sha256', secret).update(message).digest('hex');

// Constant-time comparison
try {
  var sigBuf = Buffer.from(signature, 'utf8');
  var expectedBuf = Buffer.from(expectedSig, 'utf8');

  if (sigBuf.length !== expectedBuf.length || !nodeCrypto.timingSafeEqual(sigBuf, expectedBuf)) {
    console.error('[HMAC] Signature mismatch');
    return [{ json: { valid: false, error: 'Invalid signature' } }];
  }
} catch (e) {
  console.error('[HMAC] Comparison error: ' + e.message);
  return [{ json: { valid: false, error: 'Signature verification failed' } }];
}

console.log('[HMAC] Signature valid for action=' + body.action + ' invoice_id=' + body.invoice_id);

return [{
  json: {
    valid: true,
    invoice_id: body.invoice_id || '',
    action: body.action || '',
    reason: body.reason || '',
    owner_id: body.owner_id || $env.TELEGRAM_OWNER_CHAT_ID || ''
  }
}];

// Check if invoice exists and is in Pending Approval status
const items = $input.all();
const results = [];

for (const item of items) {
  const rows = item.json.data || [];

  if (rows.length === 0) {
    results.push({
      json: {
        found: false,
        error: 'Invoice not found',
        invoice_id: item.json.invoice_id || ''
      }
    });
    continue;
  }

  const row = rows[0];
  const status = (row.status || '').trim();

  if (status !== 'Pending Approval') {
    results.push({
      json: {
        found: true,
        processable: false,
        current_status: status,
        error: 'Invoice already ' + status,
        invoice_id: row.invoice_id || ''
      }
    });
    continue;
  }

  results.push({
    json: {
      found: true,
      processable: true,
      invoice_id: row.invoice_id || '',
      vendor: row.vendor || '',
      invoice_date: row.invoice_date || '',
      invoice_number: row.invoice_number || '',
      amount: row.amount || 0,
      status: status,
      confidence: row.confidence || 0,
      drive_file_link: row.drive_file_link || '',
      source: row.source || ''
    }
  });
}

return results;

// Process approval decision
const items = $input.all();
const results = [];

for (const item of items) {
  const form = item.json;  // Form submission data
  const now = new Date().toISOString();

  const decision = (form.decision || '').trim().toLowerCase();
  const isApprove = decision === 'approve';

  // Validate: reject requires reason
  if (!isApprove && (!form.reject_reason || form.reject_reason.trim() === '')) {
    results.push({
      json: {
        valid: false,
        error: 'Reject reason is required'
      }
    });
    continue;
  }

  // Build update payload for Google Sheets
  const updatePayload = {
    invoice_id: form.invoice_id || '',
    vendor: form.vendor || '',
    invoice_date: form.invoice_date || '',
    invoice_number: form.invoice_number || '',
    amount: form.amount || 0,
    status: isApprove ? 'Approved' : 'Rejected',
    updated_at: now
  };

  if (isApprove) {
    updatePayload.approved_at = now;
    updatePayload.approved_by = form.owner_id || 'owner';
    updatePayload.rejected_at = '';
    updatePayload.reject_reason = '';
  } else {
    updatePayload.approved_at = '';
    updatePayload.approved_by = '';
    updatePayload.rejected_at = now;
    updatePayload.reject_reason = form.reject_reason;
  }

  // Format amount
  const amountNum = Number(form.amount) || 0;
  const amountFormatted = 'Rp ' + amountNum.toLocaleString('id-ID');

  results.push({
    json: {
      ...updatePayload,
      valid: true,
      is_approve: isApprove,
      amount_formatted: amountFormatted,
      admin_chat_id: $env.TELEGRAM_ADMIN_CHAT_ID || '',
      owner_chat_id: form.owner_id || $env.TELEGRAM_OWNER_CHAT_ID || ''
    }
  });
}

return results;

// Build Admin notification message
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;
  const action = inv.is_approve ? 'APPROVED' : 'REJECTED';
  const emoji = inv.is_approve ? '✅' : '❌';

  let message = emoji + ' <b>Invoice ' + action + '</b>\n\n';
  message += '🏢 Vendor: ' + (inv.vendor || '-') + '\n';
  message += '🔢 No. Invoice: ' + (inv.invoice_number || '-') + '\n';
  message += '💰 Nominal: ' + (inv.amount_formatted || '-') + '\n';
  message += '📅 Tanggal: ' + (inv.invoice_date || '-') + '\n';
  message += '👤 Approved/Rejected by: ' + (inv.approved_by || inv.reject_reason || 'Owner') + '\n';

  if (!inv.is_approve) {
    message += '\n📝 Alasan Reject: ' + (inv.reject_reason || '-') + '\n';
  }

  if (inv.is_approve) {
    message += '\n💡 <b>Siap untuk eksekusi pembayaran.</b>';
  }

  results.push({
    json: {
      chatId: inv.admin_chat_id || $env.TELEGRAM_ADMIN_CHAT_ID || '',
      text: message,
      parseMode: 'HTML'
    }
  });
}

return results;

// Build Owner confirmation message
const items = $input.all();
const results = [];

for (const item of items) {
  const inv = item.json;
  const action = inv.is_approve ? 'disetujui' : 'ditolak';
  const emoji = inv.is_approve ? '✅' : '❌';

  const message =
    emoji + ' <b>Invoice ' + action + '</b>\n\n' +
    '🔢 No. Invoice: ' + (inv.invoice_number || '-') + '\n' +
    '🏢 Vendor: ' + (inv.vendor || '-') + '\n' +
    '💰 Nominal: ' + (inv.amount_formatted || '-') + '\n\n' +
    'Terima kasih. Invoice sudah diproses.';

  results.push({
    json: {
      chatId: inv.owner_chat_id || $env.TELEGRAM_OWNER_CHAT_ID || '',
      text: message,
      parseMode: 'HTML'
    }
  });
}

return results;

